&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Bourbi&#233;rin&lt;div style=&quot;float:right;&quot;&gt;FP 2&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Humano&#239;de&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Humano&#239;de.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Marais&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Marais.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire p.36&lt;/i&gt;, Codex monstrueux p.6
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 600
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (bourbi&#233;rin) de taille M, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; -1 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 18 m (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;vision nocturne&quot;&gt;vision nocturne&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +4
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 14, contact 9, pris au d&#233;pourvu 14 (armure +2, Dex -1, naturelle +3)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 22 (3d8+9)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +0, &lt;b&gt;Vig&lt;/b&gt; +5, &lt;b&gt;Vol&lt;/b&gt; +1
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 6 m (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), nage 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; morgenstern +5 (1d8+3), langue -1 (contact, langue gluante)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; coassement terrifiant
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 15, &lt;b&gt;Dex&lt;/b&gt; 9, &lt;b&gt;Con&lt;/b&gt; 14, &lt;b&gt;Int&lt;/b&gt; 8, &lt;b&gt;Sag&lt;/b&gt; 11, &lt;b&gt;Cha&lt;/b&gt; 10
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +2, &lt;b&gt;BMO&lt;/b&gt; +4, &lt;b&gt;DMD&lt;/b&gt; 13
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (morgenstern), &lt;a class=&quot;pagelink&quot; href=&quot;Robustesse.html&quot; title=&quot;Robustesse&quot;&gt;Robustesse&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +2 (+14 pour le saut), &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; -1 (+7 dans les marais), &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +10 ; &lt;b&gt;Modificateurs raciaux&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +16 pour sauter, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +8 dans les marais, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +4
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; bourbi&#233;rin
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; d&#233;placement facilit&#233; (marais), retenir son souffle
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; marais temp&#233;r&#233;s
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation sociale&lt;/b&gt; solitaire, couple ou arm&#233;e (3-12)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; &#233;quipement de PNJ (armure de cuir, morgenstern, autres tr&#233;sors)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Particularit&#233;s&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Coassement terrifiant (Sur)&lt;/b&gt; Une fois par heure, chaque bourbi&#233;rin peut utiliser une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; pour pousser un puissant et terrifiant coassement. Toutes les cr&#233;atures (autres que des bourbi&#233;rins) situ&#233;es dans un rayon de 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) doivent r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 13 pour ne pas &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secou&#233;es&lt;/a&gt; pendant 1d4 rounds. Celles qui r&#233;ussissent ce &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; ne peuvent plus &#234;tre affect&#233;es par le coassement du bourbi&#233;rin pendant les 24 heures qui suivent. Les cr&#233;atures qui &#233;taient d&#233;j&#224; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secou&#233;es&lt;/a&gt; deviennent &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Effray&#233;.html&quot; title=&quot;Effray&#233;&quot;&gt;effray&#233;es&lt;/a&gt; pendant 1d4 rounds. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; d&#233;pend du &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; et inclut un bonus racial de +2.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;D&#233;placement facilit&#233; (marais) (Ext)&lt;/b&gt; Les bourbi&#233;rins peuvent traverser tous les terrains naturels difficiles &#224; leur vitesse normale pour autant qu&#39;ils se trouvent dans un marais. Les terrains modifi&#233;s par magie ont cependant leur effet normal.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langue gluante (Ext)&lt;/b&gt; Lorsqu&#39;une cr&#233;ature a &#233;t&#233; touch&#233;e par l&#39;attaque de langue du boubi&#233;rin, elle ne peut plus s&#39;&#233;loigner de plus de 3 m (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) de lui et elle subit une p&#233;nalit&#233; de -2 &#224; la CA tant que la langue du bourbi&#233;rin reste attach&#233;e (ces p&#233;nalit&#233;s ne se cumulent pas si plusieurs langues sont attach&#233;es). La victime peut d&#233;tacher la langue en r&#233;ussissant un test de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; oppos&#233; (par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;) ou en lui infligeant 2 points de d&#233;g&#226;ts de type tranchant (la langue &#224; une CA de 11 et les d&#233;g&#226;ts inflig&#233;s ne sont pas appliqu&#233;s au bourbi&#233;rin). Le bourbi&#233;rin non plus ne peut pas s&#39;&#233;loigner de plus de 3 m (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) de la victime pais il peut d&#233;tacher sa langue par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;. Contrairement aux &lt;a class=&quot;pagelink&quot; href=&quot;Grenouille-G&#233;ante.html&quot; title=&quot;Grenouille, Grenouille g&#233;ante&quot;&gt;grenouilles g&#233;antes&lt;/a&gt;, les bourbi&#233;rins ne peuvent pas utiliser leur langue pour attirer la victime vers eux.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Retenir son souffle (Ext)&lt;/b&gt; Un bourbi&#233;rin peut retenir sa respiration pendant un nombre de rounds &#233;gal &#224; quatre fois sa valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; avant de risquer de se noyer ou de suffoquer.
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes de bourbi&#233;rins&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;Bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin-Balafr&#233;.html&quot; title=&quot;Bourbi&#233;rin, Bourbi&#233;rin balafr&#233;&quot;&gt;Bourbi&#233;rin balafr&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin-Sauvage.html&quot; title=&quot;Bourbi&#233;rin, Bourbi&#233;rin sauvage&quot;&gt;Bourbi&#233;rin sauvage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brute-Bourbi&#233;rine.html&quot; title=&quot;Bourbi&#233;rin, Brute bourbi&#233;rine&quot;&gt;Brute bourbi&#233;rine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Champion bourbi&#233;rin&quot;&gt;Champion bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Chasseur bourbi&#233;rin&quot;&gt;Chasseur bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grandcoasseur-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Grandcoasseur bourbi&#233;rin&quot;&gt;Grandcoasseur bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Abyssal-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Guerrier abyssal bourbi&#233;rin&quot;&gt;Guerrier abyssal bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oracle-Du-Marais-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Oracle du marais bourbi&#233;rin&quot;&gt;Oracle du marais bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Roi-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Pr&#234;tre-roi bourbi&#233;rin&quot;&gt;Pr&#234;tre-roi bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Proph&#232;te-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Proph&#232;te bourbi&#233;rin&quot;&gt;Proph&#232;te bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Traqueur bourbi&#233;rin&quot;&gt;Traqueur bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;9&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;i&gt;Deux yeux globuleux dominent la t&#234;te de crapaud de cette cr&#233;ature &#224; la peau verte recouverte de verrues et de protub&#233;rances.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les bourbi&#233;rins ressemblent &#224; des hommes-crapauds ou &#224; des hommes-grenouilles dot&#233;s de mains et de pieds palm&#233;s, de grands yeux et de bouches d&#233;mesur&#233;ment larges. Ces cr&#233;atures s’installent pr&#232;s des grandes rivi&#232;res ou dans les profondeurs des marais. Elles construisent de petits villages compos&#233;s de monticules de boue sur les rives des fleuves. &lt;br /&gt;&lt;br /&gt;Les bourbi&#233;rins naissent sous forme de t&#234;tards dans des &#233;tangs de reproduction puis grandissent jusqu’&#224; atteindre 90 cm de longueur avant de d&#233;velopper des bras et des jambes et de pouvoir vivre sur terre. Arriv&#233;s &#224; ce stade, les jeunes bourbi&#233;rins doivent chasser et tuer un humano&#239;de pour &#234;tre accept&#233;s dans le clan. Ceux qui &#233;chouent sont exil&#233;s. &lt;br /&gt;&lt;br /&gt;En vieillissant, les bourbi&#233;rins continuent de grandir et se d&#233;colorent peu &#224; peu. Les bourbi&#233;rins exceptionnellement &#226;g&#233;s poss&#232;dent une peau enti&#232;rement blanche et sont tr&#232;s corpulents. Certains de ces individus font partie de la caste des pr&#234;tres-rois et m&#232;nent une vie de plaisirs macabres &#224; la t&#234;te de leur clan.&lt;br /&gt;&lt;br /&gt;Les bourbi&#233;rins se tiennent souvent vo&#251;t&#233;s. Ils mesurent 1,50 m&#232;tre et p&#232;sent pr&#232;s de 100 kg. Ils peuvent vivre pendant 50 ans mais les rudesses de la vie dans les marais et les combats intestins r&#233;duisent souvent leur esp&#233;rance de vie.
&lt;/div&gt;&lt;br /&gt;&lt;center&gt;&lt;img src=&quot;/wiki/public/upload/Bestiaire/Bourbierin Bogwynne.jpg&quot; width=&quot;90%&quot; style=&quot;float: none; margin: 5px;&quot;/&gt;&lt;/center&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;&#201;cologie des bourbi&#233;rins&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;cologie_des_bourbi&#233;rins_0&quot; href=&quot;#&#201;cologie_des_bourbi&#233;rins_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les bourbi&#233;rins vivent dans des mar&#233;cages humides et infest&#233;s de maladies, souvent &#224; l’&#233;cart des autres communaut&#233;s humano&#239;des, ce qui les pousse &#224; se m&#233;fier des visiteurs &#233;trangers, de leurs id&#233;es et de leurs technologies. &#192; force de se marginaliser ainsi, ils ont d&#233;velopp&#233; leur violence au point que les forts tyrannisent et d&#233;vorent souvent les individus les plus faibles.&lt;br /&gt;&lt;br /&gt;Les pr&#234;tres-rois (ce terme s’appliquant aussi bien aux hommes qu’aux femmes) occupent le sommet de la hi&#233;rarchie. Ce sont des proph&#232;tes tyranniques qui r&#232;gnent sur une foule de sujets incultes.&lt;br /&gt;&lt;br /&gt;La vie du bourbi&#233;rin commence dans une fray&#232;re, sous forme d’oeuf g&#233;latineux, chaque ponte en produisant une dizaine. Apr&#232;s un mois de gestation, les t&#234;tards grignotent l’enveloppe de l’oeuf pour en sortir et passent neuf mois &#224; se nourrir de tout ce qu’ils trouvent, y compris leurs fr&#232;res plus faibles. Ils d&#233;veloppent des jambes et des bras minuscules qui s’allongent rapidement et prennent assez de forces pour leur permettre de ramper hors de leur mare. Cet exploit ne suffit pourtant pas &#224; leur assurer une place dans la soci&#233;t&#233; des bourbi&#233;rins car des gardiens &#233;liminent alors les plus faibles et tout individu pr&#233;sentant un signe de difformit&#233;.&lt;br /&gt;&lt;br /&gt;Les rejetons des pr&#234;tres-rois constituent une exception : ils sont nourris &#224; base de libellules empoisonn&#233;es. Ce r&#233;gime tue la plupart des t&#234;tards et les rares survivants ne se d&#233;veloppent pas comme les autres bourbi&#233;rins. Certains pr&#233;sentent des capacit&#233;s intellectuelles et magiques sup&#233;rieures qui en font de futurs pr&#234;tres-rois, mais la majorit&#233; des survivants deviennent des horreurs ch&#233;tives et idiotes appel&#233;es des bourbgigoteurs.&lt;br /&gt;&lt;br /&gt;Les jeunes bourbi&#233;rins vivent en unit&#233;s regroupant un peu plus d’une dizaine d’adolescents supervis&#233;s par une poign&#233;e de guerriers exp&#233;riment&#233;s. Au cours de leur premi&#232;re ann&#233;e hors de l’eau, les jeunes re&#231;oivent une protection et des soins minimaux tandis qu’ils acqui&#232;rent les talents pratiques indispensables pour assurer leur survie et servir leur roi. Tous les bourbi&#233;rins re&#231;oivent le m&#234;me entra&#238;nement qui se concentre principalement sur les prouesses athl&#233;tiques, l’art de la chasse et un large &#233;ventail de travaux artisanaux rudimentaires.&lt;br /&gt;&lt;br /&gt;Quand le bourbi&#233;rin atteint les trois ans, il est consid&#233;r&#233; comme un adulte et quitte la communaut&#233; pendant un mois au cours duquel il se livre &#224; une chasse rituelle. S’il revient avec le cadavre d’un humano&#239;de intelligent, il est reconnu par ses pairs et obtient une place dans la soci&#233;t&#233; bourbi&#233;rine qui donne un grand festin en son honneur. S’il &#233;choue, il est exil&#233; ou d&#233;vor&#233;.&lt;br /&gt;&lt;br /&gt;Les pr&#234;tres-rois sont bien plus gros que leurs fr&#232;res. Parfois, ils sont tellement boursoufl&#233;s et ob&#232;ses qu’on croirait qu’ils appartiennent &#224; une autre esp&#232;ce. Leur monopole sur la magie divine renforce d’autant plus le foss&#233; entre le monarque et ses sujets. Quand le pr&#234;tre-roi au pouvoir tr&#233;passe (souvent de mort violente), ses h&#233;ritiers entrent en comp&#233;tition pour le tr&#244;ne. Le vainqueur tue g&#233;n&#233;ralement tous ses fr&#232;res et soeurs pour asseoir son pouvoir.&lt;br /&gt;&lt;br /&gt;Les bourbi&#233;rins sont tr&#232;s fertiles et leur culture les encourage &#224; se reproduire aussi souvent que leurs ressources le permettent. Malgr&#233; le grand nombre de t&#234;tards, le cannibalisme syst&#233;matique des bourbi&#233;rins maintient leur population &#224; un niveau raisonnable. Les bourbi&#233;rins consid&#232;rent cette pratique comme une m&#233;thode pour &#233;liminer les faibles et consolider les forts, mais comme ils s’y livrent d&#232;s leur plus jeune &#226;ge, il semble que le cannibalisme soit, en r&#233;alit&#233;, instinctif, comme une expression de leur app&#233;tit vorace. Toutefois, comme les adultes ont surv&#233;cu &#224; leurs fr&#232;res issus de nombreuses pontes et &#224; un environnement obligeant &#224; la concurrence, ils sont tr&#232;s adaptables et se montrent capables de survivre &#224; un d&#233;sastre &#233;cologique et d’&#233;voluer pour exploiter au mieux leur nouvel environnement, au grand dam des autres cr&#233;atures intelligentes qui se retrouvent en comp&#233;tition avec eux.&lt;br /&gt;&lt;br /&gt;Le bourbi&#233;rin &#171; typique &#187; est adapt&#233; &#224; la vie dans les marais, mais d’autres vivent dans les for&#234;ts tropicales et pr&#233;sentent souvent une peau aux motifs color&#233;s. Les bourbi&#233;rins sont capables d’entrer en estivation, comme les amphibiens auxquels ils ressemblent, pour survivre aux p&#233;riodes de s&#233;cheresse et de disette. Il arrive donc, m&#234;me si cela reste extr&#234;mement rare, que des bourbi&#233;rins exploitent les p&#233;riodes de pluie dans les d&#233;serts. Ils sont alors particuli&#232;rement agressifs.&lt;br /&gt;&lt;br /&gt;Les villages bourbi&#233;rins sont souvent dispos&#233;s de mani&#232;re &#224; renforcer la hi&#233;rarchie. La demeure du pr&#234;tre-roi se trouve sur une butte de boue compact&#233;e, aux allures de ziggourat, situ&#233;e au coeur de la communaut&#233;. Les buttes de ses subalternes directs se trouvent tout autour. Plus la butte du bourbi&#233;rin est &#233;lev&#233;e et proche de celle du monarque, plus ce bourbi&#233;rin occupe une place &#233;lev&#233;e dans la hi&#233;rarchie. Ces cr&#233;atures affichent aussi leur importance en d&#233;corant leur abri avec des os, des coquilles, des roseaux et divers mat&#233;riaux exotiques. Si un bourbi&#233;rin vole les d&#233;corations de son voisin, le conflit se r&#232;gle dans une explosion de violence, mais si le voleur est victorieux… C’est qu’il avait visiblement bien raison de prendre ce qu’il voulait.&lt;br /&gt;&lt;br /&gt;Un bourbi&#233;rin passe la majeure partie de sa vie &#224; chasser et cueillir. Leur artisanat se limite g&#233;n&#233;ralement &#224; de simples constructions de pierre et de mati&#232;re organique. Certains pr&#234;tres-rois font volontairement tourner les &#233;quipes travaillant sur tel ou tel projet, afin d’emp&#234;cher un bourbi&#233;rin de prouver qu’il est exceptionnellement dou&#233;. Et ce que les bourbi&#233;rins ne peuvent fabriquer ou r&#233;cup&#233;rer, ils le volent aux autres humano&#239;des. Le m&#233;tal est tr&#232;s rare au sein de leur soci&#233;t&#233;, principalement parce qu’il ne r&#233;siste pas &#224; une exposition prolong&#233;e &#224; un environnement humide. Les armes et armures magiques sont donc tr&#232;s pris&#233;es pour leur r&#233;sistance &#224; la corrosion.&lt;br /&gt;&lt;br /&gt;La vie spirituelle et religieuse des bourbi&#233;rins est centr&#233;e sur deux croyances. Tout d’abord : il faut recycler les faibles pour renforcer les puissants, qu’il s’agisse de d&#233;vorer un infirme, de r&#233;cup&#233;rer les armes d’un fr&#232;re mort ou de voler la maison d’un voisin. Ensuite, force fait loi, surtout pour le pr&#234;tre-roi qui re&#231;oit g&#233;n&#233;ralement ses pouvoirs divins d’une divinit&#233; mal&#233;fique ou d’un seigneur d&#233;mon. Les bourbi&#233;rins se reposent sur leur chef pour les guider spirituellement, ce qui en fait souvent des idiots superstitieux. Les individus qui refusent les croyances de la soci&#233;t&#233; bourbi&#233;rine sont exil&#233;s et les bourbi&#233;rins qui entendent parler de ces ermites ressentent un d&#233;dain m&#234;l&#233; de malaise.&lt;br /&gt;&lt;br /&gt;La m&#233;tamorphose fascine les bourbi&#233;rins, qu’il s’agisse du d&#233;veloppement de leurs petits ou de la transformation de leur pr&#234;tre-roi. Une personne qui n&#233;gocie avec des bourbi&#233;rins a une chance de les &#233;merveiller en usant d’une magie transformatrice.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Traits raciaux alternatifs&lt;a class=&quot;headeranchor&quot; id=&quot;Traits_raciaux_alternatifs_4&quot; href=&quot;#Traits_raciaux_alternatifs_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Vous pouvez remplacer les traits raciaux habituels des bourbi&#233;rins par les suivants.
&lt;div class=&quot;row Ligne&quot; style=&quot;&quot;&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;&lt;b&gt;Estivation.&lt;/b&gt; Les marais ne sont pas tous humides toute l’ann&#233;e et certains bourbi&#233;rins ont d&#251; s’adapter pour survivre dans des marais saisonniers qui traversent aussi des p&#233;riodes chaudes et arides. Un bourbi&#233;rin dot&#233; de ce don racial peut passer une heure &#224; s’enfouir dans la terre humide ou meuble, afin d’entrer dans un &#233;tat d’animation suspendue pendant un temps ind&#233;fini. Tant qu’il estive, le bourbi&#233;rin n’a pas besoin de manger ni de boire, mais il subit les m&#234;mes malus aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; que s’il dormait. Il lui faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; pour mettre un terme &#224; sa dormance. Ce trait racial remplace celui accordant un bonus racial aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour sauter.&lt;/li&gt;&lt;li&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;&lt;b&gt;Sauteur.&lt;/b&gt; Dans certaines r&#233;gions, les bourbi&#233;rins ont des pattes plus adapt&#233;es aux mouvements explosifs sur la terre ferme qu’&#224; la propulsion sous l’eau. On consid&#232;re que ces bourbi&#233;rins ont toujours une course d’&#233;lan quand ils tentent un test d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour sauter, mais leur vitesse de nage est r&#233;duite de 4,50 m&#232;tres.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;&lt;b&gt;Pr&#234;tre-roi.&lt;/b&gt; Les bourbi&#233;rins &#233;lev&#233;s avec de la pulpe de libellule bleue deviennent parfois des pr&#234;tres-rois. Ils ont un bonus d’armure naturelle de +2 seulement mais ne subissent pas le malus racial de –2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; et &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; commun aux autres membres de leur race. De plus, ils re&#231;oivent un bonus racial de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; et b&#233;n&#233;ficient des pouvoirs magiques suivants : 1/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nappe-De-Brouillard.html&quot; title=&quot;Nappe de brouillard&quot;&gt;nappe de brouillard&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nu&#233;e-Grouillante.html&quot; title=&quot;Nu&#233;e grouillante&quot;&gt;nu&#233;e grouillante&lt;/a&gt;&lt;/i&gt;. Leur niveau de lanceur de sorts est &#233;gal &#224; leurs &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt;. Ce trait racial ne remplace pas les autres, il vient en sus, mais il est extr&#234;mement rare et le MJ est le seul &#224; pouvoir l’attribuer.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Bonus alternatifs de classe de pr&#233;dilection&lt;a class=&quot;headeranchor&quot; id=&quot;Bonus_alternatifs_de_classe_de_pr&#233;dilection_5&quot; href=&quot;#Bonus_alternatifs_de_classe_de_pr&#233;dilection_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Voici les options ouvertes aux bourbi&#233;rins dot&#233;s de la classe de pr&#233;dilection indiqu&#233;e. Le bonus s’applique &#224; chaque fois que le personnage choisit la r&#233;compense de classe, sauf indication contraire.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;row Ligne&quot; style=&quot;&quot;&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;b&gt;Barbare.&lt;/b&gt; Ajoutez 1 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; du barbare quand il saute.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Barde.&lt;/b&gt; R&#233;duisez le temps de rechargement entre deux coassements terrifiants de 5 minutes (5 minutes au minimum).&lt;br /&gt;&lt;br /&gt;&lt;/div&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;b&gt;Guerrier.&lt;/b&gt; Augmentez les points de vie de la langue du guerrier de 1 et ajoutez 1/2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; oppos&#233;s quand il tente d’emp&#234;cher une cr&#233;ature de se d&#233;tacher de sa langue.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#244;deur.&lt;/b&gt; Ajoutez 1/4 au bonus d’un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENVIRONNEMENTDEPREDILECTION&quot; title=&quot;Le r&#244;deur&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt; d&#233;j&#224; choisi (au maximum +2 par environnement de pr&#233;dilection).&lt;br /&gt;&lt;br /&gt;&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Nouvelles r&#232;gles raciales&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_r&#232;gles_raciales_6&quot; href=&quot;#Nouvelles_r&#232;gles_raciales_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les r&#232;gles suivantes pr&#233;sentent des dons, des sorts et des objets magiques sp&#233;cialement con&#231;us pour les bourbi&#233;rins.
&lt;h3 class=&quot;separator&quot;&gt;Dons&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_1&quot; href=&quot;#Dons_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici quelques dons tr&#232;s appr&#233;ci&#233;s des bourbi&#233;rins.
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche filtrable&quot; WIDTH=&quot;100%&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Src&lt;/td&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;37%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coassement-&#201;tourdissant.html&quot; title=&quot;Coassement &#233;tourdissant&quot;&gt;Coassement &#233;tourdissant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coassement-Supersonique.html&quot; title=&quot;Coassement supersonique&quot;&gt;Coassement supersonique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sac-Vocal.html&quot; title=&quot;Sac vocal&quot;&gt;Sac vocal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;bourbi&#233;rin&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;coassement terrifiant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&#201;tourdit les cr&#233;atures avec le coassement&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coassement-Supersonique.html&quot; title=&quot;Coassement supersonique&quot;&gt;Coassement supersonique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sac-Vocal.html&quot; title=&quot;Sac vocal&quot;&gt;Sac vocal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;bourbi&#233;rin&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;coassement terrifiant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Inflige des d&#233;g&#226;ts de son avec le coassement&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coassement-Suppl&#233;mentaire.html&quot; title=&quot;Coassement suppl&#233;mentaire&quot;&gt;Coassement suppl&#233;mentaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;Bourbi&#233;rin&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;coassement terrifiant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain d&#39;une utilisation par heure suppl&#233;mentaire du coassement terrifiant&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Langue-Puissante.html&quot; title=&quot;Langue puissante&quot;&gt;Langue puissante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;For&quot;&gt;For&lt;/a&gt; 17, &lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;langue gluante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain du pouvoir attirer avec la langue&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sac-Vocal.html&quot; title=&quot;Sac vocal&quot;&gt;Sac vocal&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;Bourbi&#233;rin&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;coassement terrifiant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Augmente la port&#233;e du coassement terrifiant&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
&lt;div class=&quot;row ligne&quot; style=&quot;&quot;&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
